-- 앱 버그 신고 (Flyway V24). 빗물받이 제보(report)와는 별개

CREATE TABLE "bug_report" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL REFERENCES "users" ("id"),
  "category" varchar(30) NOT NULL,
  "title" varchar(100) NOT NULL,
  "content" varchar(2000) NOT NULL,
  "screen" varchar(200),
  "request_id" varchar(64),
  "app_version" varchar(50),
  "platform" varchar(20),
  "user_agent" varchar(500),
  "photo_keys" varchar(1000),
  "status" varchar(20) NOT NULL DEFAULT 'RECEIVED',
  "admin_note" varchar(1000),
  "resolved_by" bigint REFERENCES "users" ("id"),
  "resolved_at" timestamp,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp
);

CREATE INDEX idx_bug_report_status_created ON "bug_report" ("status", "created_at" DESC);
CREATE INDEX idx_bug_report_user_created ON "bug_report" ("user_id", "created_at" DESC);

COMMENT ON TABLE "bug_report" IS '앱 버그 신고 (사용자 → 운영팀)';
COMMENT ON COLUMN "bug_report"."category" IS 'ERROR(오류 · 멈춤) / UI(화면 이상) / FEATURE(기능이 안 됨) / PERFORMANCE(느림) / OTHER';
COMMENT ON COLUMN "bug_report"."title" IS '신고 제목 (2~100자)';
COMMENT ON COLUMN "bug_report"."content" IS '신고 내용 (개인정보가 섞일 수 있어 로그에 남기지 않는다)';
COMMENT ON COLUMN "bug_report"."screen" IS '버그가 난 화면 · 경로 (프론트가 보냄)';
COMMENT ON COLUMN "bug_report"."request_id" IS '프론트가 마지막으로 받은 X-Request-Id (로그 추적용)';
COMMENT ON COLUMN "bug_report"."platform" IS 'WEB / IOS / ANDROID (선택)';
COMMENT ON COLUMN "bug_report"."user_agent" IS '서버가 User-Agent 헤더에서 채움 (500자에서 자름)';
COMMENT ON COLUMN "bug_report"."photo_keys" IS '스크린샷 S3 key 최대 3개, 쉼표로 구분';
COMMENT ON COLUMN "bug_report"."status" IS 'RECEIVED(접수) / IN_PROGRESS(확인 중) / RESOLVED(해결) / WONT_FIX(보류)';
COMMENT ON COLUMN "bug_report"."admin_note" IS '관리자 내부 메모 (신고자에게 보여주지 않는다)';
COMMENT ON COLUMN "bug_report"."resolved_by" IS 'RESOLVED · WONT_FIX로 바꾼 관리자';
